import{createAjuWindPackets}from'./wind-packets.mjs';
import{AJU as R}from'./registration.mjs';import{PINS}from'./asset-pins.mjs';import{prepareAjuSupport,pinnedBytes}from'./support.mjs';import{createNight}from'./night.mjs';import{claimWind,windPhase,REV}from'./wind.mjs';import{createGrassStepR2,composeContactLayerR2}from'./contact-multi-r2.mjs';
export async function prepareAjuRegion({signal,fetcher=fetch,decode=b=>createImageBitmap(new Blob([b],{type:'image/png'})),canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}={}){
 let packets=createAjuWindPackets({signal,fetcher,decode});let closed=false,support,engine,frames=[],lastFoot=null,cfg,anchors,wc,night,nightUnlit;const images=new Map,canvases=[],roots=new Map,phases=[];const check=()=>{if(closed||signal?.aborted)throw Error('AJU_ABORT')};const dispose=()=>{if(closed)return;closed=true;signal?.removeEventListener('abort',dispose);support?.dispose();packets.dispose();engine?.reset();frames=[];for(const im of images.values())im.close?.();images.clear();for(const c of canvases)c.width=c.height=1;canvases.length=0;roots.clear();phases.length=0;night=nightUnlit=null;lastFoot=null;engine=null;cfg=anchors=wc=null};
 const canvas=(w,h)=>{const c=canvasFactory(w,h);canvases.push(c);return c},read=async n=>{check();const b=await pinnedBytes(PINS[n],{signal,fetcher});check();return b},json=async n=>JSON.parse(new TextDecoder().decode(await read(n)));
 let base,sort,actor,one,wind,windSort,fx,work;
 try{support=await prepareAjuSupport({signal,fetcher});cfg=await json('config.json');anchors=await json('anchors.json');wc=await json('wind_contract.json');const manifest=await json('night-manifest.json');night=createNight(manifest,new Uint32Array(await read('light.u32')),new Float64Array(await read('light.f64')));nightUnlit=createNight({...manifest,count:0},new Uint32Array(0),new Float64Array(0));
 const sizes={ASSEMBLED_FULL:[1536,1024],CLEAN_GROUND_FULL:[1536,1024],wind_sprites64:[4608,288]};for(const n of Object.keys(PINS).filter(n=>n.endsWith('.png')&&!['floor.png','player.png','MATERIAL_ID.png','wind_sprites64.png','wind_background64.png','wind_background64_NE.png','wind_background64_SW.png','wind_background64_SE.png'].includes(n))){const im=await decode(await read(n));images.set(n,im);check();const expected=sizes[n.replace('.png','')]??(n.startsWith('wind_background')?[2400,1760]:n.startsWith('fixed_roots')?[300,220]:n.startsWith('phase')?[64,40]:[72,72]);if(im.width!==expected[0]||im.height!==expected[1])throw Error('AJU_IMAGE_SHAPE')}
 work=canvas(300,220);const g=work.getContext('2d');for(const region of Object.keys(cfg.regions)){g.clearRect(0,0,300,220);g.drawImage(images.get('fixed_roots_'+region+'.png'),0,0);roots.set(region,g.getImageData(0,0,300,220).data)}work.width=64;work.height=40;for(let i=0;i<4;i++){g.clearRect(0,0,64,40);g.drawImage(images.get('phase'+i+'.png'),0,0);phases.push(g.getImageData(0,0,64,40).data)}
 engine=createGrassStepR2({sceneId:'AJU_FOUR_R1',materialContains:f=>!!support.wildZone(f),safe49:support.safe});[base,sort,actor,one,wind,windSort,fx]=Array.from({length:7},()=>canvas(960,540));check();signal?.addEventListener('abort',dispose,{once:true});
 }catch(e){dispose();throw e}
 function render({camera,elapsedMs=0,nightMix=0,actors=[],moving=false,windEnabled=true,windRest=false,lightsEnabled=true,contacts=null}={}){
 check();if(!Array.isArray(camera)||camera.length!==4||!camera.every(Number.isInteger))throw Error('AJU_CAMERA');const[x,y,w,h]=camera;if(x<0||y<0||w<1||h<1||x+w>1536||y+h>1024||w>1536||h>1024||!Number.isFinite(elapsedMs)||elapsedMs<0||!Number.isFinite(nightMix)||nightMix<0||nightMix>1)throw Error('AJU_FRAME');if(windEnabled&&!windRest&&![0,32].includes(windPhase(elapsedMs))&&!packets.ready(elapsedMs))return null;if(!moving&&contacts===null){engine.reset();frames=[];lastFoot=null}else if(moving&&contacts===null&&lastFoot){frames=engine.sample({sceneId:'AJU_FOUR_R1',foot:lastFoot,movedDistance:0,nowMs:elapsedMs,movementIntent:true,subpixelDeferred:true}).frames}
 for(const c of[base,sort,actor,one,wind,windSort,fx]){if(c.width!==w)c.width=w;if(c.height!==h)c.height=h;const z=c.getContext('2d');z.clearRect(0,0,w,h);z.imageSmoothingEnabled=false}
 const bg=base.getContext('2d'),sg=sort.getContext('2d'),ag=actor.getContext('2d'),og=one.getContext('2d'),wg=wind.getContext('2d'),ws=windSort.getContext('2d'),fg=fx.getContext('2d'),depth=new Int32Array(w*h);depth.fill(-1);const sorted=[...actors].sort((a,b)=>a.foot[1]-b.foot[1]);
 const drawActor=(g,a)=>g.drawImage(a.image,a.origin[0]-x,a.origin[1]-y,a.width,a.height);
 for(const a of sorted){og.clearRect(0,0,w,h);drawActor(og,a);const rgba=og.getImageData(0,0,w,h).data;for(let p=0;p<depth.length;p++)if(rgba[p*4+3])depth[p]=a.foot[1];drawActor(ag,a)}const ad=ag.getImageData(0,0,w,h).data;
 bg.drawImage(images.get('ASSEMBLED_FULL.png'),x,y,w,h,0,0,w,h);bg.drawImage(actor,0,0);
 const composeSorted=(g,animated,phase)=>{g.drawImage(images.get('CLEAN_GROUND_FULL.png'),x,y,w,h,0,0,w,h);let ai=0;for(const p of anchors){while(ai<sorted.length&&p.depthY>sorted[ai].foot[1])drawActor(g,sorted[ai++]);if(animated&&['NW','NE','SW','SE'].includes(p.region))packets.drawSprite(g,p.variant,phase,p.origin[0]-x,p.origin[1]-y);else g.drawImage(images.get('CLUMP_'+p.variant+'_NATIVE72_RGBA.png'),p.origin[0]-x,p.origin[1]-y)}while(ai<sorted.length)drawActor(g,sorted[ai++])};
 composeSorted(sg,false,0);const fd=bg.getImageData(0,0,w,h),sd=sg.getImageData(0,0,w,h).data,contact=composeContactLayerR2({contacts:contacts??frames,phaseRGBA:phases,width:w,height:h,origin:[x,y]});for(let p=0;p<depth.length;p++)if(ad[p*4+3]&&Math.floor(p/w)+y>=depth[p]-24&&!contact.pixels[p*4+3])fd.data.set(sd.subarray(p*4,p*4+4),p*4);
 const phase=windPhase(elapsedMs),legacy=fd.data.slice();let used=false;wg.drawImage(images.get('ASSEMBLED_FULL.png'),x,y,w,h,0,0,w,h);const protectedRoots=new Uint8Array(w*h);
 for(const [region,r]of Object.entries(cfg.regions)){const meta={enabled:windEnabled,rest:windRest,conflict:false,proofVerified:true,region,revision:REV,sourceSHA:wc.sourceSHA,proofSHA:wc.proofSHA,worldMs:elapsedMs,applied:new Set};if(!claimWind(meta,wc))continue;used=true;const[ox,oy]=r.origin;if(phase!==0&&phase!==32)packets.drawBackground(wg,region,phase,ox-x,oy-y);const root=roots.get(region);for(let ry=0;ry<220;ry++)for(let rx=0;rx<300;rx++){const dx=ox+rx-x,dy=oy+ry-y;if(dx>=0&&dx<w&&dy>=0&&dy<h&&root[(ry*300+rx)*4])protectedRoots[dy*w+dx]=1}}
 if(used&&phase!==0&&phase!==32){wg.drawImage(actor,0,0);composeSorted(ws,true,phase);const wf=wg.getImageData(0,0,w,h).data,wd=ws.getImageData(0,0,w,h).data;for(let p=0;p<depth.length;p++){const j=p*4;if(ad[j+3]&&Math.floor(p/w)+y>=depth[p]-24&&!contact.pixels[j+3])wf.set(wd.subarray(j,j+4),j);if(protectedRoots[p]||contact.pixels[j+3])wf.set(legacy.subarray(j,j+4),j)}fd.data.set(wf)}
 bg.putImageData(fd,0,0);const ci=fg.createImageData(w,h);ci.data.set(contact.pixels);fg.putImageData(ci,0,0);bg.drawImage(fx,0,0);const output=bg.getImageData(0,0,w,h);(lightsEnabled?night:nightUnlit)(output.data,[x,y],w,h,nightMix);return output;
 }
 return Object.freeze({...support,requestWindFrame:ms=>packets.request(ms),windPacketStats:()=>packets.stats(),get pinsVerified(){return !closed},render,draw(ctx,options){const out=render(options);if(!out)return false;ctx.putImageData(out,0,0);return true},noteStep(from,to,elapsedMs){check();if(!support.safe(from)||!support.safe(to)||Math.abs(from[0]-to[0])+Math.abs(from[1]-to[1])!==1)throw Error('AJU_CARDINAL');if(!lastFoot||lastFoot[0]!==from[0]||lastFoot[1]!==from[1]){engine.reset();engine.sample({sceneId:'AJU_FOUR_R1',foot:from,movedDistance:0,nowMs:elapsedMs})}lastFoot=[...to];frames=engine.sample({sceneId:'AJU_FOUR_R1',foot:to,movedDistance:1,nowMs:elapsedMs,movementIntent:true}).frames},resetContact(){check();frames=engine.reset().frames;lastFoot=null},dispose});
}
